attributes.input_schema:
  {
      "type": "object",
      "properties": {
          "index": {
              "type": "string",
              "description": "OpenSearch index name"
          },
          "question": {
              "type": "string",
              "description": "Natural language question to query data from opensearch index"
          }
      }
  },
  "strict": false
}

{
  "type": "object",
  "properties": {
    "index": {
      "type": "string",
      "description": "OpenSearch index name"
    },
    "doc_id": {
      "type": "string",
      "description": "Target document ID"
    },
    "timestamp_field": {
      "type": "string",
      "description": "Timestamp field for ordering (e.g., @timestamp)"
    },
    "count": {
      "type": "integer",
      "description": "Number of documents before and after the target"
    }
  },
  "required": ["index", "doc_id", "timestamp_field", "count"],
  "additionalProperties": false
}
